'use client';

import { motion, type Transition } from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { CircleAlertIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/registry/ndeko/ui/command';
import { SelectedMark } from '@/registry/ndeko/ui/selected-mark';

import { MorphLabel } from './_parts/morph-label';
import { TeamTile } from './_parts/team-tile';
import { TEAMS, memberCountLabelOf } from './_parts/teams';

const TRAVEL: Transition = { type: 'spring', bounce: 0, duration: 0.3 };
const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return TRAVEL;
}

function teamById(teamId: string) {
  const found = TEAMS.find((team) => team.id === teamId);
  if (found) {
    return found;
  }
  return TEAMS[0];
}

export default function Teams09() {
  const shouldReduceMotion = usePrefersReducedMotion();
  const markId = useId();
  const [query, setQuery] = useState('');
  const [teamId, setTeamId] = useState(TEAMS[0].id);
  const current = teamById(teamId);
  const travel = travelOf(shouldReduceMotion);

  function clearSearch() {
    setQuery('');
  }

  return (
    <Command
      label='Move FRN-148 to a team'
      className='bg-card hairline-ring ring-border h-auto w-full max-w-[22rem] shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <div className='flex items-center gap-2 px-3 pt-3 pb-2 text-xs'>
        <span
          role='img'
          aria-label='Bug'
          className='gem-plate inline-flex size-4 shrink-0 items-center justify-center rounded-[5px] [--gem:var(--destructive)]'
        >
          <CircleAlertIcon strokeWidth={2.5} className='size-2.5' />
        </span>
        <span className='text-muted-foreground tabular-nums'>FRN-148</span>
        <span className='text-muted-foreground'>in</span>
        <span aria-live='polite' className='font-medium'>
          <MorphLabel value={current.id}>{current.name}</MorphLabel>
        </span>
      </div>
      <CommandInput
        value={query}
        onValueChange={setQuery}
        placeholder='Move to a team'
        aria-label='Find a team'
      />
      <AnimatedSize>
        <CommandList className='max-h-72'>
          <CommandEmpty className='flex flex-col items-center gap-2 py-6'>
            <span>No team matches “{query}”</span>
            <Button size='sm' variant='outline' onClick={clearSearch}>
              Clear search
            </Button>
          </CommandEmpty>
          <CommandGroup heading='Teams'>
            {TEAMS.map((team) => {
              const isCurrent = team.id === teamId;
              return (
                <CommandItem
                  key={team.id}
                  value={team.name}
                  onSelect={() => setTeamId(team.id)}
                  aria-current={isCurrent}
                  className='h-9'
                >
                  <TeamTile initials={team.initials} color={team.color} />
                  <span className='min-w-0 flex-1 truncate'>{team.name}</span>
                  <span className='text-muted-foreground text-xs tabular-nums'>
                    {memberCountLabelOf(team.memberCount)}
                  </span>
                  <span className='flex w-[18px] justify-end'>
                    {isCurrent && (
                      <motion.span
                        layoutId={markId}
                        transition={travel}
                        className='flex'
                      >
                        <SelectedMark label='Current team' />
                      </motion.span>
                    )}
                  </span>
                </CommandItem>
              );
            })}
          </CommandGroup>
        </CommandList>
      </AnimatedSize>
    </Command>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

const ARRIVE: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const LEAVE: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const BLUR_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)', transition: ARRIVE },
  exit: { opacity: 0, filter: 'blur(2px)', transition: LEAVE },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: ARRIVE },
  exit: { opacity: 0, transition: LEAVE },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return BLUR_VARIANTS;
}

type MorphLabelProps = {
  /** Changes when the label becomes another one. */
  value: string;
  className?: string;
  children: React.ReactNode;
};

/** A label that becomes another: the text crossfades through a light blur while its width follows. */
export function MorphLabel({ value, className, children }: MorphLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={value}
          variants={variantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          className={cn('flex whitespace-nowrap', className)}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

const SIZE_CLASS = {
  sm: 'size-5 rounded-[5px] text-[9px]',
  md: 'size-6 rounded-md text-[10px]',
  lg: 'size-9 rounded-lg text-xs',
} as const;

type TeamTileProps = {
  initials: string;
  color: string;
  size?: keyof typeof SIZE_CLASS;
  className?: string;
};

/** A team without a logo: its initials in white on a gem plate of its colour. */
export function TeamTile({
  initials,
  color,
  size = 'md',
  className,
}: TeamTileProps) {
  const gemStyle = { '--gem': color } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={gemStyle}
      className={cn(
        'gem-plate inline-flex shrink-0 items-center justify-center font-semibold',
        SIZE_CLASS[size],
        className
      )}
    >
      {initials}
    </span>
  );
}

export type Team = {
  id: string;
  name: string;
  initials: string;
  /** The colour the team picked for its tile. */
  color: string;
  memberIds: string[];
  memberCount: number;
};

export const TEAMS: Team[] = [
  {
    id: 'atlas',
    name: 'Atlas Redesign',
    initials: 'AR',
    color: 'var(--info)',
    memberIds: ['amara', 'leo', 'sana', 'tomas', 'mei', 'jonas'],
    memberCount: 6,
  },
  {
    id: 'field',
    name: 'Field App',
    initials: 'FA',
    color: 'var(--success)',
    memberIds: ['leo', 'sana', 'jonas'],
    memberCount: 5,
  },
  {
    id: 'growth',
    name: 'Growth',
    initials: 'GR',
    color: 'var(--warning)',
    memberIds: ['mei', 'amara'],
    memberCount: 4,
  },
  {
    id: 'platform',
    name: 'Platform',
    initials: 'PL',
    color: 'var(--primary)',
    memberIds: ['sana', 'tomas', 'jonas'],
    memberCount: 7,
  },
  {
    id: 'research',
    name: 'Research',
    initials: 'RE',
    color: 'var(--muted-foreground)',
    memberIds: ['mei'],
    memberCount: 1,
  },
];

export function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}
